<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Sorting Algorithm Visualizer</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background: #0f0f1a;
    color: #e0e0e0;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 20px;
  }
  h1 {
    margin-bottom: 20px;
    color: #ffffff;
    font-size: 28px;
    text-align: center;
  }
  #controls {
    margin-bottom: 20px;
    display: flex;
    gap: 15px;
    flex-wrap: wrap;
    justify-content: center;
  }
  button {
    background: #1f1f2e;
    color: #ffffff;
    border: 2px solid #4a90d9;
    border-radius: 8px;
    padding: 12px 24px;
    font-size: 16px;
    cursor: pointer;
    transition: all 0.2s ease;
  }
  button:hover {
    background: #4a90d9;
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(74, 144, 217, 0.4);
  }
  button:active {
    transform: translateY(0);
  }
  button:disabled {
    opacity: 0.5;
    cursor: not-allowed;
    transform: none;
    box-shadow: none;
  }
  #bars {
    display: flex;
    align-items: flex-end;
    justify-content: center;
    width: 100%;
    max-width: 900px;
    height: 450px;
    background: #1a1a2e;
    border-radius: 10px;
    padding: 10px;
    gap: 2px;
    overflow: hidden;
  }
  .bar {
    background: linear-gradient(180deg, #4a90d9, #2c5282);
    border-radius: 3px 3px 0 0;
    width: 100%;
    min-width: 2px;
    height: 0;
    transition: height 0.3s ease, background 0.2s ease;
    display: flex;
    align-items: flex-end;
    justify-content: center;
  }
  .bar.highlight {
    background: linear-gradient(180deg, #ffeb3b, #fbc02d);
  }
  .bar.sorted {
    background: linear-gradient(180deg, #4caf50, #2e7d32);
  }
  #status {
    margin-top: 15px;
    font-size: 14px;
    color: #a0a0a0;
  }
</style>
</head>
<body>
  <h1>Sorting Algorithm Visualizer</h1>
  <div id="controls">
    <button id="sort">Sort</button>
    <button id="shuffle">Shuffle</button>
    <button id="reset">Reset</button>
  </div>
  <div id="bars"></div>
  <div id="status">Ready</div>

  <script>
    (function() {
      let array = [];
      const DEFAULT_SIZE = 50;
      const MAX_VALUE = 100;

      // Visualization state
      let animating = false;
      let animationSpeed = 30; // ms per step
      let timeoutId = null;

      // Sort state (Insertion Sort)
      let sortI = 0;       // current index being inserted
      let sortJ = 0;       // current comparison index
      let sortedCount = 0; // number of elements known to be in final position

      const barsContainer = document.getElementById('bars');
      const statusEl = document.getElementById('status');

      function createBarElement(value, index) {
        const bar = document.createElement('div');
        bar.className = 'bar';
        bar.style.height = (value / MAX_VALUE * 100) + '%';
        bar.title = value;
        bar.dataset.index = index;
        return bar;
      }

      function updateBars() {
        // Clear existing bars
        barsContainer.innerHTML = '';
        for (let i = 0; i < array.length; i++) {
          const bar = createBarElement(array[i], i);
          // Add sorting highlight classes
          if (i < sortedCount) {
            bar.classList.add('sorted');
          } else if (i === sortI || i === sortJ || i === sortJ + 1) {
            bar.classList.add('highlight');
          }
          barsContainer.appendChild(bar);
        }
      }

      function generateArray(size) {
        const arr = [];
        for (let i = 0; i < size; i++) {
          arr.push(Math.floor(Math.random() * MAX_VALUE) + 1);
        }
        return arr;
      }

      function resetSortState() {
        sortI = 1;
        sortJ = sortI - 1;
        sortedCount = 0;
      }

      // Check if array is sorted ascending
      function isSorted(arr) {
        for (let i = 0; i < arr.length - 1; i++) {
          if (arr[i] > arr[i + 1]) return false;
        }
        return true;
      }

      // Public API
      window.viz = {
        array() {
          return array.slice();
        },

        setArray(a) {
          array = a.slice();
          resetSortState();
          updateBars();
          statusEl.textContent = 'Array set';
        },

        sortStep() {
          if (array.length < 2) {
            sortedCount = array.length;
            updateBars();
            return true;
          }

          if (sortI >= array.length) {
            // We've gone through all insertions
            sortedCount = array.length;
            updateBars();
            return true;
          }

          // Compare array[sortJ] with array[sortJ + 1]
          if (sortJ >= 0 && array[sortJ] > array[sortJ + 1]) {
            // Swap
            const temp = array[sortJ];
            array[sortJ] = array[sortJ + 1];
            array[sortJ + 1] = temp;
            sortJ--;
            updateBars();
          } else {
            // Move to next element
            sortI++;
            sortJ = sortI - 1;
            // Mark elements up to previous sortI as sorted
            // Actually, we mark sortedCount as the number of fully placed elements
            // In insertion sort, after processing index sortI-1, all elements 0..sortI-1 are sorted
            sortedCount = sortI;
            updateBars();
          }

          return isSorted(array);
        },

        sorted() {
          return isSorted(array);
        }
      };

      // Button event handlers
      function startSortAnimation() {
        if (animating) return;
        if (isSorted(array)) {
          statusEl.textContent = 'Already sorted';
          return;
        }
        animating = true;
        statusEl.textContent = 'Sorting...';
        animateStep();
      }

      function animateStep() {
        if (!animating) return;

        const done = window.viz.sortStep();

        if (done) {
          animating = false;
          statusEl.textContent = 'Sorted!';
          updateBars();
        } else {
          timeoutId = setTimeout(animateStep, animationSpeed);
        }
      }

      function stopAnimation() {
        animating = false;
        if (timeoutId) {
          clearTimeout(timeoutId);
          timeoutId = null;
        }
      }

      document.getElementById('sort').addEventListener('click', startSortAnimation);

      document.getElementById('shuffle').addEventListener('click', function() {
        stopAnimation();
        array = generateArray(DEFAULT_SIZE);
        resetSortState();
        updateBars();
        statusEl.textContent = 'Shuffled';
      });

      document.getElementById('reset').addEventListener('click', function() {
        stopAnimation();
        array = generateArray(DEFAULT_SIZE);
        resetSortState();
        updateBars();
        statusEl.textContent = 'Reset';
      });

      // Initialize
      array = generateArray(DEFAULT_SIZE);
      resetSortState();
      updateBars();
      statusEl.textContent = 'Ready - Click Sort to begin';
    })();
  </script>
</body>
</html>
